-- ==========================================================================
-- INSERÇÃO DE PREÇOS E MÓDULOS LIVINTUS (MOVELSUL 2026)
-- Modelos: SOFÁ OLDEN (1,50m e 1,80m), POLTRONA OLDEN e POLTRONA LUNA
-- Destinado à base de Produção (resolve IDs dinamicamente via subqueries)
-- ==========================================================================

BEGIN TRANSACTION;

-- --------------------------------------------------------------------------
-- 1. LIMPEZA PREVENTIVA DE REGISTROS INCORRETOS
-- (Remove registros criados erroneamente sob BANDINI ou CONDOR com as medidas
-- de Olden e Luna, caso o script preliminar tenha sido executado)
-- --------------------------------------------------------------------------
DELETE FROM pi.modulo_tecido 
WHERE id_modulo IN (
    SELECT m.id FROM pi.modulo m
    JOIN pi.marca ma ON m.id_marca = ma.id
    WHERE m.id_fornecedor = (SELECT id FROM pi.fornecedor WHERE UPPER(nome) = 'LIVINTUS' LIMIT 1)
      AND (
          (ma.nome = 'BANDINI' AND m.profundidade = 0.84 AND m.altura = 0.73 AND m.largura IN (1.50, 1.80))
          OR
          (ma.nome = 'CONDOR' AND m.profundidade = 0.84 AND m.largura IN (0.86, 0.80))
      )
);

DELETE FROM pi.modulo 
WHERE id_fornecedor = (SELECT id FROM pi.fornecedor WHERE UPPER(nome) = 'LIVINTUS' LIMIT 1)
  AND (
      (id_marca = (SELECT id FROM pi.marca WHERE UPPER(nome) = 'BANDINI' LIMIT 1) AND profundidade = 0.84 AND altura = 0.73 AND largura IN (1.50, 1.80))
      OR
      (id_marca = (SELECT id FROM pi.marca WHERE UPPER(nome) = 'CONDOR' LIMIT 1) AND profundidade = 0.84 AND largura IN (0.86, 0.80))
  );

-- --------------------------------------------------------------------------
-- 2. GARANTIR A EXISTÊNCIA DAS MARCAS / MODELOS
-- --------------------------------------------------------------------------
INSERT INTO pi.marca (nome, fl_ativo) SELECT 'OLDEN', true WHERE NOT EXISTS (SELECT 1 FROM pi.marca WHERE UPPER(nome) = 'OLDEN');
INSERT INTO pi.marca (nome, fl_ativo) SELECT 'POLTRONA OLDEN', true WHERE NOT EXISTS (SELECT 1 FROM pi.marca WHERE UPPER(nome) = 'POLTRONA OLDEN');
INSERT INTO pi.marca (nome, fl_ativo) SELECT 'POLTRONA LUNA', true WHERE NOT EXISTS (SELECT 1 FROM pi.marca WHERE UPPER(nome) = 'POLTRONA LUNA');

-- --------------------------------------------------------------------------
-- 3. GARANTIR A EXISTÊNCIA DOS TECIDOS / COUROS
-- --------------------------------------------------------------------------
INSERT INTO pi.tecido (nome) SELECT 'CO-5' WHERE NOT EXISTS (SELECT 1 FROM pi.tecido WHERE UPPER(nome) = 'CO-5');
INSERT INTO pi.tecido (nome) SELECT 'CO-6' WHERE NOT EXISTS (SELECT 1 FROM pi.tecido WHERE UPPER(nome) = 'CO-6');
INSERT INTO pi.tecido (nome) SELECT 'CO-7' WHERE NOT EXISTS (SELECT 1 FROM pi.tecido WHERE UPPER(nome) = 'CO-7');
INSERT INTO pi.tecido (nome) SELECT 'TC/ST' WHERE NOT EXISTS (SELECT 1 FROM pi.tecido WHERE UPPER(nome) = 'TC/ST');

-- ==========================================================================
-- MÓDULO: SOFÁ OLDEN 1,50M (PEÇA ÚNICA)
-- Medidas: Largura 1.50m | Profundidade 0.84m | Altura 0.73m | M³ 0.92
-- ==========================================================================
INSERT INTO pi.modulo (id_fornecedor, id_categoria, id_marca, descricao, largura, profundidade, altura, pa)
SELECT 
    (SELECT id FROM pi.fornecedor WHERE UPPER(nome) = 'LIVINTUS' LIMIT 1),
    (SELECT id FROM pi.categoria WHERE UPPER(nome) = 'LIVINTUS' LIMIT 1),
    (SELECT id FROM pi.marca WHERE UPPER(nome) = 'OLDEN' LIMIT 1),
    'PEÇA ÚNICA',
    1.50,
    0.84,
    0.73,
    0.00
WHERE NOT EXISTS (
    SELECT 1 FROM pi.modulo m
    WHERE m.id_fornecedor = (SELECT id FROM pi.fornecedor WHERE UPPER(nome) = 'LIVINTUS' LIMIT 1)
      AND m.id_marca = (SELECT id FROM pi.marca WHERE UPPER(nome) = 'OLDEN' LIMIT 1)
      AND m.descricao = 'PEÇA ÚNICA'
      AND m.largura = 1.50
);
UPDATE pi.modulo
SET profundidade = 0.84, altura = 0.73, pa = 0.00
WHERE id_fornecedor = (SELECT id FROM pi.fornecedor WHERE UPPER(nome) = 'LIVINTUS' LIMIT 1)
  AND id_marca = (SELECT id FROM pi.marca WHERE UPPER(nome) = 'OLDEN' LIMIT 1)
  AND descricao = 'PEÇA ÚNICA'
  AND largura = 1.50;

-- Preço CO-5: R$ 2005.00
UPDATE pi.modulo_tecido mt
SET valor_tecido = 2005.000, dt_ultima_revisao = NOW()
WHERE mt.id_modulo = (
    SELECT m.id FROM pi.modulo m
    WHERE m.id_fornecedor = (SELECT id FROM pi.fornecedor WHERE UPPER(nome) = 'LIVINTUS' LIMIT 1)
      AND m.id_marca = (SELECT id FROM pi.marca WHERE UPPER(nome) = 'OLDEN' LIMIT 1)
      AND m.descricao = 'PEÇA ÚNICA'
      AND m.largura = 1.50
    LIMIT 1
)
AND mt.id_tecido = (SELECT id FROM pi.tecido WHERE UPPER(nome) = 'CO-5' LIMIT 1)
AND mt.fl_ativo = true;

